/**
 * NFR-D53: the formatters, checked against platform/dashboard/formatters.py itself. The cases file
 * is generated by running the Python formatters (see the README), so a value prints the same in
 * both dashboards, including the binary-rounding cases (0.2395 -> 0.239) and half-even ties.
 */
import { describe, expect, it } from "vitest";
import cases from "./formatters.python-cases.json";
import {
  MISSING, csvSafeText, fmtAmount, fmtAsReceived, fmtBool, fmtClosure, fmtInterval, fmtPercent, fmtRecall, fmtSeconds,
  fmtTime, fmtTimeUtc, fmtWeight, verdictLabel,
} from "./formatters";

type Case = { v: number | null; amount?: string; percent?: string; weight?: string; recall?: string; seconds?: string; interval?: string };

describe("number formatting matches Python", () => {
  const numeric = (cases as Case[]).filter((item) => item.v !== null);
  it.each(numeric)("%o", (item) => {
    const v = item.v as number;
    expect(fmtAmount(v)).toBe(item.amount);
    expect(fmtPercent(v)).toBe(item.percent);
    expect(fmtWeight(v)).toBe(item.weight);
    expect(fmtRecall(v)).toBe(item.recall);
    expect(fmtSeconds(v)).toBe(item.seconds);
  });

  it("formats an interval as the R10 tables do", () => {
    expect(fmtInterval(0.3588, 0.2395, 0.5)).toBe((cases as Case[]).at(-1)!.interval);
    expect(fmtInterval(0.3588, 0.2395, 0.5)).toBe("0.359 [0.239, 0.500]");
  });
});

describe("formatters", () => {
  it("shows missing values as a dash", () => {
    for (const fn of [fmtAmount, fmtPercent, fmtWeight, fmtRecall, fmtSeconds, fmtAsReceived]) expect(fn(null)).toBe(MISSING);
    expect(fmtSeconds(Number.NaN)).toBe(MISSING);
    expect(fmtBool(null)).toBe(MISSING);
  });

  it("keeps the currency as named and flags a partial total", () => {
    expect(fmtAmount(90757.05, "US Dollar")).toBe("90,757.05 US Dollar");
    expect(fmtAmount(121341.16, "US Dollar", true)).toBe("121,341.16 US Dollar (partial)");
  });

  it("shows topology_prob exactly as received", () => {
    expect(fmtAsReceived(0.7280946512826214)).toBe("0.7280946512826214");
  });

  it("shows a closed loop instead of a percentage", () => {
    expect(fmtClosure(null)).toBe("closed loop");
    expect(fmtClosure(0.5, true)).toBe("closed loop");
    expect(fmtClosure(0.684)).toBe("68.4%");
  });

  it("formats times in the given zone and in UTC", () => {
    expect(fmtTimeUtc("2022-09-09T23:32:59Z")).toBe("2022-09-09 23:32:59 UTC");
    expect(fmtTimeUtc("2022-09-09T23:32:59")).toBe("2022-09-09 23:32:59 UTC");       // naive means UTC
    expect(fmtTime("2022-09-09T23:32:59Z", "UTC")).toBe("2022-09-09 23:32 UTC");
    expect(fmtTime("2022-09-09T23:32:59Z", "Asia/Kolkata")).toMatch(/^2022-09-10 05:02 /);
    expect(fmtTime("2022-09-09T23:32:59Z", "Not/AZone")).toBe("2022-09-09 23:32 UTC");
    expect(fmtTime("not a time")).toBe("not a time");
    expect(fmtTime(null)).toBe(MISSING);
  });

  it("prefixes spreadsheet formula markers", () => {
    for (const text of ["=SUM(A1)", "+1", "-1", "@x", "\tx", "\rx"]) expect(csvSafeText(text)).toBe(`'${text}`);
    expect(csvSafeText("plain")).toBe("plain");
    expect(csvSafeText(5)).toBe(5);
    expect(csvSafeText("")).toBe("");
  });

  it("tags simulated verdicts", () => {
    expect(verdictLabel({ verdict: "confirm", is_simulated: true })).toBe("confirm · Simulated");
    expect(verdictLabel({ verdict: "reject", is_simulated: false })).toBe("reject");
  });
});
